"""Process-local signature policies for registered image mirrors.

Each mirror keeps at most one signature policy naming the HMAC algorithm,
the trusted key identifiers and whether the signature must cover the layer
digest. Policies live only in process memory: a restart clears every
record, and pull-time verification is always recomputed from the request
headers against the stored policy.
"""

from __future__ import annotations

from dataclasses import dataclass

#: The two supported HMAC algorithms; matching is case-sensitive.
ALGORITHMS: tuple[str, ...] = ("hmac-sha256", "hmac-sha512")

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset({"algorithm", "keys", "cover_digest"})
_REQUIRED_FIELDS = ("algorithm", "keys", "cover_digest")


class MirrorPolicyValidationError(ValueError):
    """A signature policy payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class MirrorPolicyError(ValueError):
    """A signature policy operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class MirrorPolicy:
    """The single signature policy stored for a mirror."""

    algorithm: str
    keys: tuple[str, ...]
    cover_digest: bool

    def to_dict(self, mirror_id: str) -> dict[str, object]:
        return {
            "id": mirror_id,
            "algorithm": self.algorithm,
            "keys": list(self.keys),
            "cover_digest": self.cover_digest,
        }


def build_mirror_policy_fields(
    payload: object,
) -> tuple[str, tuple[str, ...], bool]:
    """Validate a decoded policy payload and return normalized values.

    Returns ``(algorithm, keys, cover_digest)``. The key list keeps its
    submitted order and is stored verbatim; it must be a non-empty array
    of distinct non-empty strings.
    """

    if not isinstance(payload, dict):
        raise MirrorPolicyValidationError(
            "Request body must be a JSON object."
        )

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise MirrorPolicyValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise MirrorPolicyValidationError(
                f"Missing required field: {field!r}."
            )

    algorithm = payload["algorithm"]
    if not isinstance(algorithm, str) or algorithm not in ALGORITHMS:
        allowed = ", ".join(ALGORITHMS)
        raise MirrorPolicyValidationError(
            f"Field 'algorithm' must be one of: {allowed} (case-sensitive)."
        )

    raw_keys = payload["keys"]
    if not isinstance(raw_keys, list):
        raise MirrorPolicyValidationError("Field 'keys' must be an array.")
    if not raw_keys:
        raise MirrorPolicyValidationError("Field 'keys' must not be empty.")
    keys: list[str] = []
    for element in raw_keys:
        if not isinstance(element, str):
            raise MirrorPolicyValidationError(
                "Field 'keys' elements must be strings."
            )
        if not element:
            raise MirrorPolicyValidationError(
                "Field 'keys' elements must not be empty."
            )
        if element in keys:
            raise MirrorPolicyValidationError(
                "Field 'keys' elements must not repeat."
            )
        keys.append(element)

    cover_digest = payload["cover_digest"]
    if not isinstance(cover_digest, bool):
        raise MirrorPolicyValidationError(
            "Field 'cover_digest' must be a boolean."
        )

    return algorithm, tuple(keys), cover_digest


class MirrorPolicyStore:
    """Process-local storage of at most one signature policy per mirror."""

    def __init__(self) -> None:
        self._policies: dict[str, MirrorPolicy] = {}

    def reset(self) -> None:
        self._policies = {}

    def get(self, mirror_id: str) -> MirrorPolicy | None:
        return self._policies.get(mirror_id)

    def add(
        self, mirror_id: str, payload: object
    ) -> tuple[MirrorPolicy, bool]:
        """Validate and record the signature policy for ``mirror_id``.

        Returns ``(policy, created)`` where ``created`` is ``True`` for a
        first registration (HTTP 201) and ``False`` for an idempotent
        repeat of the exact same content (HTTP 200).

        Raises :class:`MirrorPolicyValidationError` for an invalid payload
        or :class:`MirrorPolicyError` with code ``mirror_policy_conflict``
        when a different policy is already stored; the stored policy is
        never overwritten.
        """

        algorithm, keys, cover_digest = build_mirror_policy_fields(payload)
        policy = MirrorPolicy(
            algorithm=algorithm, keys=keys, cover_digest=cover_digest
        )

        existing = self._policies.get(mirror_id)
        if existing is not None:
            if existing == policy:
                return existing, False
            raise MirrorPolicyError(
                "mirror_policy_conflict",
                "A different signature policy is already registered for "
                "this mirror.",
            )

        self._policies[mirror_id] = policy
        return policy, True

"""Process-local image mirror registry and upstream layer fetching.

A mirror record pairs a globally unique ``name`` with an absolute
``http``/``https`` ``upstream`` base address. Records are kept in insertion
order and never persisted. Pulling a layer through a mirror never happens in
this module: it only knows how to fetch the raw bytes of
``<upstream>/layers/<digest>`` so the caller can verify the digest and decide
whether to populate the shared layer cache.

Everything lives in the current process memory: mirrors are lost on restart
and nothing is ever written to a file.
"""

from __future__ import annotations

import urllib.error
import urllib.request
import uuid
from dataclasses import dataclass
from typing import Any
from urllib.parse import urlsplit

#: Fetch timeout in seconds for contacting an upstream mirror.
DEFAULT_FETCH_TIMEOUT = 10.0

_ALLOWED_FIELDS = frozenset({"name", "upstream"})
_REQUIRED_FIELDS = ("name", "upstream")


class MirrorValidationError(ValueError):
    """A mirror registration payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class MirrorFetchError(Exception):
    """The upstream could not deliver a layer.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class Mirror:
    """A single registered image mirror."""

    id: str
    name: str
    upstream: str

    def to_dict(self) -> dict[str, object]:
        return {"id": self.id, "name": self.name, "upstream": self.upstream}


def _require_non_empty_string(value: object, label: str) -> str:
    if not isinstance(value, str):
        raise MirrorValidationError(f"{label} must be a string.")
    if not value.strip():
        raise MirrorValidationError(f"{label} must not be empty.")
    return value


def _build_upstream(value: object) -> str:
    upstream = _require_non_empty_string(value, "Upstream")
    parts = urlsplit(upstream)
    # A network location is required so relative addresses or bare schemes
    # are rejected; only http and https are supported.
    if parts.scheme not in ("http", "https") or not parts.netloc:
        raise MirrorValidationError(
            "Upstream must be an absolute http or https URL."
        )
    return upstream


def build_mirror_fields(payload: object) -> tuple[str, str]:
    """Validate a decoded JSON payload and return ``(name, upstream)``."""

    if not isinstance(payload, dict):
        raise MirrorValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise MirrorValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise MirrorValidationError(
                f"Missing required field: {field!r}."
            )

    name = _require_non_empty_string(payload["name"], "Name")
    upstream = _build_upstream(payload["upstream"])
    return name, upstream


class MirrorStore:
    """Process-local, insertion-ordered mirror storage with unique names."""

    def __init__(self) -> None:
        self._mirrors: list[Mirror] = []
        self._by_id: dict[str, Mirror] = {}
        self._name_to_id: dict[str, str] = {}

    def reset(self) -> None:
        self._mirrors = []
        self._by_id = {}
        self._name_to_id = {}

    def list_all(self) -> list[Mirror]:
        return list(self._mirrors)

    def get(self, mirror_id: str) -> Mirror | None:
        return self._by_id.get(mirror_id)

    def add(
        self, payload: object
    ) -> tuple[Mirror | None, Mirror | None]:
        """Validate and store a mirror.

        Returns ``(created, None)`` on success or ``(None, existing)`` when
        the name is already registered; the original mirror is never
        overwritten.
        """

        name, upstream = build_mirror_fields(payload)
        existing_id = self._name_to_id.get(name)
        if existing_id is not None:
            return None, self._by_id[existing_id]

        mirror = Mirror(id=uuid.uuid4().hex, name=name, upstream=upstream)
        self._mirrors.append(mirror)
        self._by_id[mirror.id] = mirror
        self._name_to_id[name] = mirror.id
        return mirror, None


def _layer_url(upstream: str, digest: str) -> str:
    return upstream.rstrip("/") + "/layers/" + digest


def fetch_upstream_layer(
    upstream: str,
    digest: str,
    *,
    timeout: float = DEFAULT_FETCH_TIMEOUT,
) -> bytes:
    """Fetch ``<upstream>/layers/<digest>`` and return the raw bytes.

    Raises :class:`MirrorFetchError` with code ``mirror_fetch_failed`` when
    the upstream cannot be contacted or answers a non-200 status. The
    digest comparison is the caller's responsibility.
    """

    url = _layer_url(upstream, digest)
    request = urllib.request.Request(url, method="GET")
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            if getattr(response, "status", response.getcode()) != 200:
                raise MirrorFetchError(
                    "mirror_fetch_failed",
                    "Upstream mirror did not return the layer.",
                )
            return response.read()
    except urllib.error.HTTPError as exc:
        if exc.code == 200:  # pragma: no cover - urlopen never raises on 200
            return exc.read()
        raise MirrorFetchError(
            "mirror_fetch_failed",
            "Upstream mirror did not return the layer.",
        ) from exc
    except (urllib.error.URLError, OSError, ValueError) as exc:
        raise MirrorFetchError(
            "mirror_fetch_failed",
            "Upstream mirror could not be reached.",
        ) from exc

