def _handle_mirror_item(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "GET":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="GET",
        )

    if not raw_id:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Mirror id must not be empty.",
        )
    if "/" in raw_id or "\\" in raw_id:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Mirror id must not contain path separators.",
        )

    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )

    mirror = mirror_store.get(raw_id)
    if mirror is None:
        return _error(
            start_response,
            "404 Not Found",
            "mirror_not_found",
            "No mirror exists with the requested id.",
        )

    return _json_response(
        start_response, "200 OK", mirror.to_dict(), trailing_newline=True
    )

